// PATCH fields merge member-wise by default: omitted members are kept,
// explicit nulls clear, and empty groups are no-ops. Metadata merges per key,
// with null values deleting keys. Lists replace wholesale (deletion = resend
// the list without the element), while each sent element merges onto the
// stored element of the same type when that type occurs exactly once on both
// sides. Element members that are required on create (“prompt“,
// “setup_prompt“, the monitor/triage slack configs, “scan_id“) may be
// omitted when a counterpart exists — they carry like any other member;
// explicit null is rejected.
type AutomationUpdateRequest struct {
	// nil omits the property; &[]any{} sends [] (clears it).
	Actions     *[]any                 `json:"actions,omitempty"`
	Concurrency *AutomationConcurrency `json:"concurrency,omitempty"`
	Enabled     *bool                  `json:"enabled,omitempty"`
	Limits      *AutomationLimits      `json:"limits,omitempty"`
	// The automation's LLM check configuration. On update the filter prompt is
	LlmCheck *AutomationLlmCheckRequest `json:"llm_check,omitempty"`
	// nil omits the property; &map[string]string{} sends {} (clears it).
	Metadata      *map[string]string       `json:"metadata,omitempty"`
	Name          *string                  `json:"name,omitempty"`
	Notifications *AutomationNotifications `json:"notifications,omitempty"`
	// null resets to organization.
	RunAs *DevinInlineAutomationUpdateRequestRunAsNullableValue `json:"run_as,omitempty"`
	// The automation's Preflight check configuration. On update the whole
	ScriptCheck *AutomationScriptCheckRequest `json:"script_check,omitempty"`
	// The automation's own security-profile binding: a profile_id pins that profile, {"profile_id": null} records an explicit opt-out, and explicit null reverts to inheriting from the org/enterprise. Requires the security-profile management permission.
	SecurityProfile *AutomationSecurityProfileSelection `json:"security_profile,omitempty"`
	SessionSettings *AutomationSessionSettingsInput     `json:"session_settings,omitempty"`
	// null resets to slack_users.
	SlackReplyAccess *AutomationUpdateRequestSlackReplyAccess `json:"slack_reply_access,omitempty"`
	// null resets to teams_users.
	TeamsReplyAccess *AutomationUpdateRequestTeamsReplyAccess `json:"teams_reply_access,omitempty"`
	Tools            *AutomationTools                         `json:"tools,omitempty"`
	// nil omits the property; &[]AutomationTriggerRequestInput{} sends [] (clears it).
	Triggers *[]AutomationTriggerRequestInput `json:"triggers,omitempty"`
}

