type OncallResponderCreateRequest struct {
	Enabled *bool             `json:"enabled,omitempty"`
	Limits  *AutomationLimits `json:"limits,omitempty"`
	// User-defined tags; 'team' (and 'service' when obvious) are recommended so reports can group responders.
	Metadata *map[string]string `json:"metadata,omitempty"`
	Name     string             `json:"name"`
	// The account's PagerDuty connection id; required with pagerduty:* triggers (Devin posts triage notes on the incident through it) and rejected with Slack triggers.
	PagerdutyConnectionId *string `json:"pagerduty_connection_id,omitempty"`
	// Identity triage sessions run under; defaults to organization.
	RunAs any `json:"run_as,omitempty"`
	// Investigation instructions for triage sessions. Omit (or send blank) to use the server default (`default_runbook` in the schemas response). Only supply one when the user has specific investigation steps.
	Runbook *string              `json:"runbook,omitempty"`
	Session *OncallSessionConfig `json:"session,omitempty"`
	// Omitted net_policy defaults to the deployment default policy; omitted devin_mode inherits the org default.
	SessionSettings *OncallSessionSettingsInput `json:"session_settings,omitempty"`
	// Who may reply into existing triage sessions from Slack threads: devin_users, slack_users (the organization's connected Slack workspaces), or external_slack_users (also Slack Connect users). Slack responders only.
	SlackReplyAccess *OncallResponderCreateRequestSlackReplyAccess `json:"slack_reply_access,omitempty"`
	// Slack workspace id (resolved server-side if omitted); rejected with Teams triggers, which carry team_id in conditions.
	TeamId *string `json:"team_id,omitempty"`
	// Teams responders: who may reply into existing triage sessions from Teams threads: devin_users or teams_users. Omitted = teams_users.
	TeamsReplyAccess *OncallResponderCreateRequestTeamsReplyAccess `json:"teams_reply_access,omitempty"`
	Tools            *OncallTools                                  `json:"tools,omitempty"`
	// What the responder triages, which sets its issue workflow and triage behavior: 'alerts' for monitoring alerts and pages; 'bugs' for bug reports and support questions.
	TriageIssueType OncallResponderCreateRequestTriageIssueType `json:"triage_issue_type"`
	// Up to 10 triggers from one provider, OR'd; each has its own filter and no two may be identical. Slack: slack:message, slack:usergroup_mentioned or slack:app_mentioned triggers, all in one Slack workspace. Usergroup mentioned requires a usergroup eq filter with a Slack usergroup ID. App mentioned listens on the run-as service user's own Slack app and needs no filter. Each condition group must restrict channels (eq or in) or include at least one completed filter other than is_thread_reply. PagerDuty: pagerduty:* triggers (pagerduty_connection_id required); an event type may repeat with different filters. Teams: teams:message triggers; every condition group names one team (team_id eq) and its channels (channel_id eq/in). Linear: linear:* issue triggers (team_id filters scope the watched teams; Devin comments on the issue, and replies in that thread reach the session). Jira: jira:* issue triggers (project filters scope the watched projects; Devin comments on the issue with the session link).
	Triggers []OncallTriggerRequest `json:"triggers"`
}

