// Partial update (RFC 7396-style): omitted fields and omitted group
// members keep their stored value; explicit nulls clear; “triggers“,
// “tools.mcp_servers“, “tools.slack_channels“ and “session.tags“ lists
// replace wholesale; “metadata“ merges per key (null value deletes the
// key).
type OncallResponderUpdateRequest struct {
	Enabled *bool              `json:"enabled,omitempty"`
	Limits  *OncallLimitsPatch `json:"limits,omitempty"`
	// nil omits the property; &map[string]string{} sends {} (clears it).
	Metadata *map[string]string `json:"metadata,omitempty"`
	Name     *string            `json:"name,omitempty"`
	// Omitted -> preserve; required when triggers switch the responder to PagerDuty.
	PagerdutyConnectionId *string `json:"pagerduty_connection_id,omitempty"`
	// Omitted -> preserve the responder's existing run_as; null resets to organization.
	RunAs *DevinInlineOncallResponderUpdateRequestRunAsNullableValue `json:"run_as,omitempty"`
	// Blank resets to the server default runbook.
	Runbook         *string                     `json:"runbook,omitempty"`
	Session         *OncallSessionConfig        `json:"session,omitempty"`
	SessionSettings *OncallSessionSettingsPatch `json:"session_settings,omitempty"`
	// Omitted -> preserve the responder's existing setting; null resets to slack_users.
	SlackReplyAccess *OncallResponderUpdateRequestSlackReplyAccess `json:"slack_reply_access,omitempty"`
	TeamId           *string                                       `json:"team_id,omitempty"`
	// Teams responders. Omitted -> preserve; null resets to teams_users.
	TeamsReplyAccess *OncallResponderUpdateRequestTeamsReplyAccess `json:"teams_reply_access,omitempty"`
	Tools            *OncallToolsPatch                             `json:"tools,omitempty"`
	// Replaces the trigger set. Switching provider (Slack, PagerDuty, Teams) rebuilds the responder's provider config from this request.
	Triggers *[]OncallTriggerRequest `json:"triggers,omitempty"`
}

